   where (c is null or pub.client_id=c) and (pr.kind<>'agent' or exists(select 1 from concierge.plan_task_grants tg where tg.id=g and tg.client_id=pub.client_id))
  ),page as (select * from entries where (p_command->>'cursor') is null or cursor>p_command->>'cursor' order by cursor limit (p_command->>'limit')::integer+1),bounded as (select * from page order by cursor limit (p_command->>'limit')::integer)
  select jsonb_build_object('drafts',coalesce(jsonb_agg(item order by cursor) filter(where kind='draft'),'[]'::jsonb),'publications',coalesce(jsonb_agg(item order by cursor) filter(where kind='publication'),'[]'::jsonb),'nextCursor',case when (select count(*) from page)>(p_command->>'limit')::integer then max(cursor) end) into result from bounded;
 else perform concierge.fail('invalid_input');end if;
 -- Last live check also covers waits in target-agent/source/payment rows inside an action branch.
 perform concierge.plan_session(u,sid);
 if a not in ('read_client_plan_v1','record_decision_v1') then perform concierge.plan_authorize(a,did,c,g);end if;
 if a='record_decision_v1' then perform concierge.plan_care_access(c,true);end if;
 if req is not null then insert into concierge.plan_requests values(u,req,p_command,fp,result,c,did,g);end if;
 return result;
exception when unique_violation then perform concierge.fail('revision_conflict');return null;
 when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow or invalid_datetime_format then perform concierge.fail('invalid_input');return null;
end $$;
-- Persisted, whole-candidate barriers. A request GUC or client-selected format cannot opt out.
create function concierge.plan_single_authoring() returns trigger language plpgsql set search_path='' as $$
declare c uuid:=new.client_id;begin
 if not (select activated from concierge.plan_policy where singleton) or c is null then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended('concierge:client:'||c::text,0));
 if TG_TABLE_NAME='plan_drafts' then
  if new.state='working' and exists(select 1 from concierge.drafts where client_id=c) and not exists(select 1 from concierge.plan_legacy_adoptions where client_id=c) then perform concierge.fail('legacy_draft_conflict');end if;
 elsif exists(select 1 from concierge.plan_drafts where client_id=c) or exists(select 1 from concierge.plan_legacy_adoptions where client_id=c) then perform concierge.fail('content_version_required');end if;
 return new;
end $$;
create trigger plan_single_authoring before insert or update on concierge.plan_drafts for each row execute function concierge.plan_single_authoring();
create trigger plan_legacy_draft_frozen before insert or update on concierge.drafts for each row execute function concierge.plan_single_authoring();
create trigger plan_legacy_presentation_frozen before insert or update on concierge.draft_presentations for each row execute function concierge.plan_single_authoring();
create function concierge.plan_block_legacy_guidance() returns trigger language plpgsql set search_path='' as $$begin
 if (select activated from concierge.plan_policy where singleton) and (TG_TABLE_NAME<>'publications' or (to_jsonb(new)->>'document_schema_version')::integer<>3) then perform concierge.fail('content_version_required');end if;
 return new;
end $$;
create trigger plan_publication_format_guard before insert on concierge.publications for each row execute function concierge.plan_block_legacy_guidance();
create trigger plan_instruction_barrier before insert on concierge.instruction_publications for each row execute function concierge.plan_block_legacy_guidance();
create trigger plan_review_barrier before insert on concierge.service_reviews for each row execute function concierge.plan_block_legacy_guidance();
create trigger plan_reply_barrier before insert on concierge.checkin_replies for each row execute function concierge.plan_block_legacy_guidance();
create function concierge.plan_complete_publication() returns trigger language plpgsql security definer set search_path='' as $$
declare p concierge.publications;doc concierge.plan_documents;r concierge.plan_publication_receipts;ap concierge.plan_approvals;d concierge.plan_drafts;pr concierge.plan_principals;pol concierge.plan_policy;body jsonb;begin
 select * into p from concierge.publications where client_id=new.client_id and version=new.version;
 if p.document_schema_version<>3 then if TG_TABLE_NAME='plan_documents' then perform concierge.fail('content_version_required');end if;return null;end if;
 select * into pol from concierge.plan_policy where singleton for share;
 if pol.activated is distinct from true then perform concierge.fail('candidate_inactive');end if;
 select * into doc from concierge.plan_documents where client_id=p.client_id and version=p.version;
 select * into r from concierge.plan_publication_receipts where client_id=p.client_id and version=p.version;
 select * into ap from concierge.plan_approvals where id=doc.approval_id;
 select * into d from concierge.plan_drafts where id=ap.draft_id;
 if doc.client_id is null or r.id is null or ap.id is null or d.id is null or doc.receipt_id<>r.id or doc.approval_id<>r.approval_id or ap.target is distinct from concierge.plan_exact(d) or ap.target->>'clientId'<>p.client_id::text or p.published_by<>r.actor_id or r.actor_id is distinct from auth.uid() or r.session_id is distinct from (auth.jwt()->>'session_id')::uuid or ap.publisher->>'actorId'<>r.actor_id::text or d.state<>'published' or p.intake_version is not null or p.recommendations<>'[]'::jsonb then perform concierge.fail('approval_conflict');end if;
 perform concierge.plan_authorize('publish_plan_v1',d.id,d.client_id,r.grant_id);perform concierge.plan_target_client(p.client_id);perform concierge.plan_care_access(p.client_id,true);
 if (pol.require_kanuj_approval or ap.publisher->>'kind'='task_agent') and ap.approved_by<>pol.owner_actor_id or exists(select 1 from concierge.plan_approval_revocations where approval_id=ap.id) then perform concierge.fail('approval_conflict');end if;
 perform 1 from concierge.plan_principals where actor_id=ap.approved_by and active and kind in ('owner','human') for share;if not found then perform concierge.fail('forbidden');end if;
 perform concierge.capability(ap.approved_by,'edit');
 select content into body from concierge.plan_draft_private where draft_id=d.id;
 perform concierge.plan_content_check(body,d.id,d.client_id,r.grant_id);
 if d.basis_manifest is distinct from (concierge.plan_basis(p.client_id)||jsonb_build_object('publicationVersion',nullif(p.version-1,0))) or exists(select 1 from jsonb_array_elements(concierge.plan_issues(d)) i where i->>'code'<>'basis_conflict') then perform concierge.fail('not_ready');end if;
 if doc.document is distinct from concierge.plan_client_content(body) or not exists(select 1 from concierge.entitled_publications where client_id=p.client_id and version=p.version) or not exists(select 1 from concierge.plan_events where id=r.event_id and client_id=p.client_id and publication_version=p.version) or (select count(*) from concierge.plan_deliveries where event_id=r.event_id and recipient_id=p.client_id and channel in ('email','portal'))<>2 or not exists(select 1 from concierge.plan_requests where actor_id=r.actor_id and request_id=r.request_id and result=r.receipt and command->>'action'='publish_plan_v1' and command->'target'=ap.target and command->>'approvalId'=ap.id::text) then perform concierge.fail('incomplete_publication');end if;
 if p.version=1 and (r.first_service_claim_id is null or not exists(select 1 from concierge.payment_confirmations pc join concierge.service_periods sp on sp.claim_id=pc.claim_id where pc.claim_id=r.first_service_claim_id and pc.client_id=p.client_id and pc.service_cents>0 and sp.starts_on=(p.published_at at time zone 'America/Chicago')::date) or not exists(select 1 from concierge.plan_review_schedule where client_id=p.client_id and first_publication_at=p.published_at)) then perform concierge.fail('payment_required');end if;
 return null;
end $$;
create constraint trigger plan_complete_publication after insert on concierge.publications deferrable initially deferred for each row execute function concierge.plan_complete_publication();
create constraint trigger plan_complete_document after insert on concierge.plan_documents deferrable initially deferred for each row execute function concierge.plan_complete_publication();
create function concierge.plan_journal_collision() returns trigger language plpgsql set search_path='' as $$begin
 perform pg_advisory_xact_lock(hashtextextended('concierge:request:'||new.actor_id::text||':'||new.request_id::text,0));
 if exists(select 1 from concierge.plan_requests where actor_id=new.actor_id and request_id=new.request_id) then perform concierge.fail('request_conflict');end if;return new;
end $$;
create trigger plan_r1_request_collision before insert on concierge.requests for each row execute function concierge.plan_journal_collision();
create trigger plan_workflow_request_collision before insert on concierge.workflow_requests for each row execute function concierge.plan_journal_collision();
-- Freeze the prior public entry points privately, preserve their exact ACLs at the public wrapper.
do $ddl$ declare n text;prior text;begin
 foreach n in array array['concierge_write','concierge_presentation_write','concierge_advisor_write','concierge_service_write','concierge_checkin_write'] loop
  prior:='plan_legacy_'||substr(n,11);
  execute format('alter function public.%I(uuid,text,bigint,uuid,jsonb) set schema concierge',n);
  execute format('alter function concierge.%I(uuid,text,bigint,uuid,jsonb) rename to %I',n,prior);
  execute format($body$create function public.%I(p_client_id uuid,p_action text,p_expected_revision bigint,p_request_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $fn$
  declare pol concierge.plan_policy;stored jsonb;stored_fp bytea;wanted bytea;begin
   select * into pol from concierge.plan_policy where singleton for share;
   if pol.activated and p_action in ('save_draft','save_draft_v2') then
    perform concierge.plan_guard();perform concierge.plan_target_client(p_client_id);
    if (select kind from concierge.plan_principals where actor_id=auth.uid())='agent' then perform concierge.fail('forbidden');end if;
    perform pg_advisory_xact_lock(hashtextextended('concierge:request:'||auth.uid()::text||':'||p_request_id::text,0));
    perform pg_advisory_xact_lock(hashtextextended('concierge:client:'||p_client_id::text,0));
    perform concierge.plan_guard();perform concierge.plan_target_client(p_client_id);
    if exists(select 1 from concierge.plan_drafts where client_id=p_client_id) or exists(select 1 from concierge.plan_legacy_adoptions where client_id=p_client_id) then perform concierge.fail('content_version_required');end if;
   end if;
   if pol.activated and p_action in ('publish','publish_v2','publish_instruction_revision','record_review','send_advisor_reply') then
    perform concierge.plan_guard();perform concierge.plan_target_client(p_client_id,false);
    if (select kind from concierge.plan_principals where actor_id=auth.uid())='agent' then perform concierge.fail('forbidden');end if;
    perform concierge.capability(auth.uid(),case when p_action in ('publish','publish_v2','publish_instruction_revision') then 'publish' else 'edit' end);
    perform pg_advisory_xact_lock(hashtextextended('concierge:request:'||auth.uid()::text||':'||p_request_id::text,0));perform pg_advisory_xact_lock(hashtextextended('concierge:client:'||p_client_id::text,0));
    perform concierge.plan_guard();perform concierge.plan_target_client(p_client_id,false);
    if %L='concierge_write' then
     select result,fingerprint into stored,stored_fp from concierge.requests where actor_id=auth.uid() and request_id=p_request_id and client_id=p_client_id;
     wanted:=sha256(convert_to(jsonb_build_array(p_client_id,p_action,p_expected_revision,p_payload)::text,'UTF8'));
    else
     select result,fingerprint into stored,stored_fp from concierge.workflow_requests where actor_id=auth.uid() and request_id=p_request_id and client_id=p_client_id;
     wanted:=concierge.workflow_fingerprint(p_client_id,%L,p_action,p_expected_revision,p_payload);
    end if;
    if stored is null then perform concierge.fail('content_version_required');end if;
    if stored_fp is distinct from wanted then perform concierge.fail('request_conflict');end if;
    return stored;
   end if;
   if pol.activated and p_action in ('submit_report','reserve_photo','complete_photo') then
    perform concierge.plan_session(auth.uid(),(auth.jwt()->>'session_id')::uuid);
    if auth.uid() is distinct from p_client_id then perform concierge.fail('forbidden');end if;
    perform concierge.plan_care_access(p_client_id,true);
   end if;
   if exists(select 1 from concierge.publications where client_id=p_client_id and document_schema_version=3) and p_action in ('save_draft','save_draft_v2','decide','receive','start','save_instruction_draft') then perform concierge.fail('content_version_required');end if;
   stored:=concierge.%I(p_client_id,p_action,p_expected_revision,p_request_id,p_payload);
   if pol.activated and p_action in ('submit_report','reserve_photo','complete_photo') then
    -- The legacy writer holds the existing request/client locks, including
    -- its cached-return branch. Denial here rolls back all its effects.
    perform concierge.plan_care_access(p_client_id,true);
    perform concierge.plan_session(auth.uid(),(auth.jwt()->>'session_id')::uuid);
   end if;
   return stored;
  end $fn$ $body$,n,n,case n when 'concierge_presentation_write' then 'presentation' when 'concierge_service_write' then 'service' when 'concierge_checkin_write' then 'checkin' else 'advisor' end,prior);
  execute format('revoke all on function concierge.%I(uuid,text,bigint,uuid,jsonb) from public,anon,authenticated,service_role',prior);
  execute format('revoke all on function public.%I(uuid,text,bigint,uuid,jsonb) from public,anon,service_role',n);
  execute format('grant execute on function public.%I(uuid,text,bigint,uuid,jsonb) to authenticated',n);
 end loop;
end $ddl$;
-- Old readers cannot silently project a truncated V3 plan. Existing R1/R2 bytes stay untouched.
do $ddl$ declare n text;prior text;args text;invoke text;c text;begin
 foreach n in array array['concierge_client_view','concierge_client_view_v2','concierge_advisor_view','concierge_advisor_view_v2','concierge_advisor_preview_v2'] loop
  prior:='plan_legacy_'||substr(n,11);
  if n='concierge_advisor_preview_v2' then args:='p_client_id uuid,p_mode text,p_expected_revision bigint default null';invoke:='p_client_id,p_mode,p_expected_revision';c:='p_client_id';
  elsif n like 'concierge_advisor_view%%' then args:='p_client_id uuid';invoke:='p_client_id';c:='p_client_id';else args:='';invoke:='';c:='auth.uid()';end if;
  execute format('alter function public.%I(%s) set schema concierge',n,replace(replace(replace(replace(args,'p_client_id ',''),'p_mode ',''),'p_expected_revision ',''),' default null',''));
  execute format('alter function concierge.%I(%s) rename to %I',n,replace(replace(replace(replace(args,'p_client_id ',''),'p_mode ',''),'p_expected_revision ',''),' default null',''),prior);
  execute format($body$create function public.%I(%s) returns jsonb language plpgsql security definer set search_path='' as $fn$ begin
   if (select activated from concierge.plan_policy where singleton) then
    perform concierge.plan_session(auth.uid(),(auth.jwt()->>'session_id')::uuid);
    if %s=auth.uid() then
     perform concierge.plan_target_client(auth.uid(),false);
     if exists(select 1 from concierge.entitled_publications where client_id=auth.uid()) then perform concierge.plan_care_access(auth.uid());end if;
    else perform concierge.plan_guard();end if;
   end if;
   if exists(select 1 from concierge.publications where client_id=%s and document_schema_version=3) then
    perform concierge.plan_session(auth.uid(),(auth.jwt()->>'session_id')::uuid);perform concierge.access(%s,case when %s is distinct from auth.uid() then 'view' end);perform concierge.fail('content_version_required');
   end if;
   return concierge.%I(%s);end $fn$ $body$,n,args,c,c,c,c,prior,invoke);
  execute format('revoke all on function concierge.%I(%s) from public,anon,authenticated,service_role',prior,replace(replace(replace(replace(args,'p_client_id ',''),'p_mode ',''),'p_expected_revision ',''),' default null',''));
  execute format('revoke all on function public.%I(%s) from public,anon,service_role',n,replace(replace(replace(replace(args,'p_client_id ',''),'p_mode ',''),'p_expected_revision ',''),' default null',''));
  execute format('grant execute on function public.%I(%s) to authenticated',n,replace(replace(replace(replace(args,'p_client_id ',''),'p_mode ',''),'p_expected_revision ',''),' default null',''));
 end loop;
end $ddl$;

-- Common current guards, with care access separate from surviving administration.
-- Payment evidence is administrative; check-in reports/replies/photos are care.
create function concierge.plan_legacy_read_guard(c uuid,care boolean) returns void language plpgsql set search_path='' as $$begin
 if (select activated from concierge.plan_policy where singleton for share) then
  perform concierge.plan_session(auth.uid(),(auth.jwt()->>'session_id')::uuid);
  perform concierge.plan_target_client(c,false);
  if auth.uid()=c then
   if care then perform concierge.plan_care_access(c);end if;
  else perform concierge.plan_guard();perform concierge.capability(auth.uid(),'view');end if;
 end if;
end $$;
alter function concierge.service_projection_data(uuid,boolean) rename to plan_legacy_service_projection_data;
create function concierge.service_projection_data(c uuid,advisor boolean) returns jsonb language plpgsql set search_path='' as $$
declare result jsonb;care_visible boolean:=true;begin
 perform concierge.plan_legacy_read_guard(c,false);
 if not advisor and (select activated from concierge.plan_policy where singleton) then
  care_visible:=exists(select 1 from concierge.entitled_publications where client_id=c) and concierge.plan_care_window(c)<>'expired';
 end if;
 result:=concierge.plan_legacy_service_projection_data(c,advisor);
 if not care_visible then result:=result||jsonb_build_object('reviews','[]'::jsonb,'instructions','[]'::jsonb);end if;
 return result;
end $$;
revoke all on function concierge.service_projection_data(uuid,boolean) from public,anon,authenticated,service_role;
alter function public.concierge_checkin_read(uuid) set schema concierge;
alter function concierge.concierge_checkin_read(uuid) rename to plan_legacy_checkin_read;
create function public.concierge_checkin_read(p_client_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin
 perform concierge.plan_legacy_read_guard(p_client_id,true);
 result:=concierge.plan_legacy_checkin_read(p_client_id);
 perform concierge.plan_legacy_read_guard(p_client_id,true);return result;
end $$;
alter function public.concierge_checkin_advisor_read(uuid) set schema concierge;
alter function concierge.concierge_checkin_advisor_read(uuid) rename to plan_legacy_checkin_advisor_read;
create function public.concierge_checkin_advisor_read(p_client_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin
 perform concierge.plan_legacy_read_guard(p_client_id,true);
 result:=concierge.plan_legacy_checkin_advisor_read(p_client_id);
 perform concierge.plan_legacy_read_guard(p_client_id,true);return result;
end $$;
alter function public.concierge_checkin_photo_authorize(uuid,uuid) set schema concierge;
alter function concierge.concierge_checkin_photo_authorize(uuid,uuid) rename to plan_legacy_checkin_photo_authorize;
create function public.concierge_checkin_photo_authorize(p_client_id uuid,p_photo_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin
 perform concierge.plan_legacy_read_guard(p_client_id,true);
 result:=concierge.plan_legacy_checkin_photo_authorize(p_client_id,p_photo_id);
 perform concierge.plan_legacy_read_guard(p_client_id,true);return result;
end $$;
revoke all on function public.concierge_checkin_read(uuid),public.concierge_checkin_advisor_read(uuid),public.concierge_checkin_photo_authorize(uuid,uuid) from public,anon,service_role;
grant execute on function public.concierge_checkin_read(uuid),public.concierge_checkin_advisor_read(uuid),public.concierge_checkin_photo_authorize(uuid,uuid) to authenticated;

-- Fixed internal delivery seam for a future real worker. No recipient address/raw clinical content.
-- Claim commits before contacting a provider. A lost result remains uncertain and uses delivery ID as idempotency key.
create function concierge.plan_claim_email_deliveries(p_limit integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare d concierge.plan_deliveries;lease uuid;rows jsonb:='[]';begin
 if p_limit is null or p_limit not between 1 and 50 then perform concierge.fail('invalid_input');end if;
 for d in select * from concierge.plan_deliveries where channel='email' and status='queued' order by id for update skip locked limit p_limit loop
  lease:=gen_random_uuid();update concierge.plan_deliveries set status='claimed',lease_id=lease,lease_until=clock_timestamp()+interval '5 minutes',attempts=attempts+1,revision=revision+1,updated_at=clock_timestamp() where id=d.id;
  insert into concierge.plan_delivery_attempts(delivery_id,lease_id,attempt) values(d.id,lease,d.attempts+1);
  rows:=rows||jsonb_build_array(jsonb_build_object('deliveryId',d.id,'leaseId',lease,'recipientId',d.recipient_id,'eventId',d.event_id,'idempotencyKey',d.id));
 end loop;
 return rows;
end $$;
create function concierge.plan_record_email_result(p_delivery_id uuid,p_lease_id uuid,p_status text,p_provider_message_id text,p_error_code text) returns jsonb language plpgsql security definer set search_path='' as $$
declare d concierge.plan_deliveries;begin
 if p_delivery_id is null or p_lease_id is null or p_status is null or p_status not in ('accepted','failed','uncertain') or length(coalesce(p_provider_message_id,''))>200 or coalesce(p_error_code,'') !~ '^[a-z0-9_]{0,80}$' then perform concierge.fail('invalid_input');end if;
 select * into d from concierge.plan_deliveries where id=p_delivery_id and channel='email' for update;
 if not found or d.lease_id is distinct from p_lease_id then perform concierge.fail('revision_conflict');end if;
 if d.status<>'claimed' then
  if d.status=p_status and d.provider_message_id is not distinct from p_provider_message_id and d.last_error_code is not distinct from p_error_code then return jsonb_build_object('deliveryId',d.id,'status',d.status,'revision',d.revision);end if;
  perform concierge.fail('revision_conflict');
 end if;
 update concierge.plan_deliveries set status=p_status,provider_message_id=p_provider_message_id,last_error_code=p_error_code,revision=revision+1,updated_at=clock_timestamp() where id=d.id returning * into d;
 update concierge.plan_delivery_attempts set result=p_status,provider_message_id=p_provider_message_id,recorded_at=clock_timestamp() where delivery_id=d.id and lease_id=p_lease_id;
 return jsonb_build_object('deliveryId',d.id,'status',d.status,'revision',d.revision);
end $$;
create function concierge.plan_retry_email_delivery(p_delivery_id uuid,p_expected_revision bigint,p_provider_reconciled boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare d concierge.plan_deliveries;begin
 if p_delivery_id is null or p_expected_revision is null or p_expected_revision not between 0 and 9007199254740991 or p_provider_reconciled is null then perform concierge.fail('invalid_input');end if;
 select * into d from concierge.plan_deliveries where id=p_delivery_id and channel='email' for update;
 if not found or d.revision is distinct from p_expected_revision or d.status not in ('failed','uncertain') or d.status='uncertain' and p_provider_reconciled is distinct from true then perform concierge.fail('revision_conflict');end if;
 update concierge.plan_deliveries set status='queued',revision=revision+1,lease_id=null,lease_until=null,updated_at=clock_timestamp() where id=d.id returning * into d;
 return jsonb_build_object('deliveryId',d.id,'status',d.status,'revision',d.revision);
end $$;
create function concierge.plan_expire_email_leases() returns integer language plpgsql security definer set search_path='' as $$
declare n integer;begin
 update concierge.plan_deliveries set status='uncertain',revision=revision+1,last_error_code='lease_expired',updated_at=clock_timestamp() where channel='email' and status='claimed' and lease_until<clock_timestamp();get diagnostics n=row_count;return n;
end $$;
-- No public notification/source commands advertise completion before those modules exist.
do $$ declare t record;f record;begin
 for t in select tablename from pg_tables where schemaname='concierge' and tablename like 'plan\_%' escape '\' loop
  execute format('alter table concierge.%I enable row level security',t.tablename);
  execute format('revoke all on table concierge.%I from public,anon,authenticated,service_role',t.tablename);
 end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='concierge' and p.proname like 'plan\_%' escape '\' loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 end loop;
 for t in select tablename from pg_tables where schemaname='concierge' and tablename in ('plan_source_adoptions','plan_legacy_adoptions','plan_section_reviews','plan_approvals','plan_approval_revocations','plan_task_grants','plan_task_revocations','plan_checkpoints','plan_policy_audit','plan_events','plan_publication_receipts','plan_documents','plan_review_schedule','plan_requests') loop
  execute format('create trigger plan_immutable before update on concierge.%I for each row execute function concierge.immutable()',t.tablename);
 end loop;
end $$;
revoke all on function public.concierge_plan_command_v1(jsonb) from public,anon,service_role;
grant execute on function public.concierge_plan_command_v1(jsonb) to authenticated;
-- Fixed service-only RPCs. Private schema/table/helper access remains revoked.
create function public.concierge_plan_delivery_claim_v1(p_limit integer) returns jsonb language sql security definer set search_path='' as $$select concierge.plan_claim_email_deliveries(p_limit)$$;
create function public.concierge_plan_delivery_result_v1(p_delivery_id uuid,p_lease_id uuid,p_status text,p_provider_message_id text,p_error_code text) returns jsonb language sql security definer set search_path='' as $$select concierge.plan_record_email_result(p_delivery_id,p_lease_id,p_status,p_provider_message_id,p_error_code)$$;
create function public.concierge_plan_delivery_retry_v1(p_delivery_id uuid,p_expected_revision bigint,p_provider_reconciled boolean) returns jsonb language sql security definer set search_path='' as $$select concierge.plan_retry_email_delivery(p_delivery_id,p_expected_revision,p_provider_reconciled)$$;
create function public.concierge_plan_delivery_expire_v1() returns integer language sql security definer set search_path='' as $$select concierge.plan_expire_email_leases()$$;
revoke all on function public.concierge_plan_delivery_claim_v1(integer),public.concierge_plan_delivery_result_v1(uuid,uuid,text,text,text),public.concierge_plan_delivery_retry_v1(uuid,bigint,boolean),public.concierge_plan_delivery_expire_v1() from public,anon,authenticated;
grant execute on function public.concierge_plan_delivery_claim_v1(integer),public.concierge_plan_delivery_result_v1(uuid,uuid,text,text,text),public.concierge_plan_delivery_retry_v1(uuid,bigint,boolean),public.concierge_plan_delivery_expire_v1() to service_role;
commit;
